'use strict';
const fs = require('fs'),
  path = require('path');
// Race explosion is generated by scripts/build-game-sounds.cjs.
// Card cue is built by convert-quacks-sounds.cjs; current draw/stop voices use convert-quacks-action-sounds.cjs.

const crypto = require('node:crypto'),
  target = path.join(__dirname, '../public/assets/game-sounds'),
  manifest = JSON.parse(fs.readFileSync(path.join(target, 'quacks-manifest.json'), 'utf8'));

// Original 420 ms warm settlement chime; each confirmation shares a short cue.
const settleMs = 420,
  settleFrames = settleMs * 24,
  settleBytes = Buffer.alloc(44 + settleFrames * 2);
settleBytes.write('RIFF');
settleBytes.writeUInt32LE(settleBytes.length - 8, 4);
settleBytes.write('WAVEfmt ', 8);
settleBytes.writeUInt32LE(16, 16);
settleBytes.writeUInt16LE(1, 20);
settleBytes.writeUInt16LE(1, 22);
settleBytes.writeUInt32LE(24000, 24);
settleBytes.writeUInt32LE(48000, 28);
settleBytes.writeUInt16LE(2, 32);
settleBytes.writeUInt16LE(16, 34);
settleBytes.write('data', 36);
settleBytes.writeUInt32LE(settleFrames * 2, 40);
let settlePeak = 0;
for (let i = 0; i < settleFrames; i++) {
  const t = i / 24000,
    fade = Math.max(0, Math.min(1, t / 0.012, (settleFrames - 1 - i) / 960)),
    e = Math.exp(-t * 6);
  const v = Math.round(
    (Math.sin(2 * Math.PI * 523.25 * t) * 0.23 +
      Math.sin(2 * Math.PI * 783.99 * t) * 0.12 +
      Math.sin(2 * Math.PI * 1046.5 * t) * 0.045) *
      e *
      fade *
      32767,
  );
  settleBytes.writeInt16LE(v, 44 + i * 2);
  settlePeak = Math.max(settlePeak, Math.abs(v));
}
const settleFile = 'quacks-settlement.wav';
fs.writeFileSync(path.join(target, settleFile), settleBytes);
manifest.settlement = {
  file: settleFile,
  durationMs: settleMs,
  bytes: settleBytes.length,
  sha256: crypto.createHash('sha256').update(settleBytes).digest('hex'),
  peak: settlePeak,
  source:
    'Project-original synthesis: three warm sine tones and faded envelopes, no third-party sample',
  generator: 'tools/generate-quacks-sounds.cjs',
};
fs.writeFileSync(
  path.join(target, 'quacks-manifest.json'),
  JSON.stringify(manifest, null, 2) + String.fromCharCode(10),
);
